#ifndef SITE_PROGRAM_DESTRAT_CONTROLLER_GEN_H
#define SITE_PROGRAM_DESTRAT_CONTROLLER_GEN_H

#include <cstdint>

#include "libbotanik.h"

#include "../../../vars.h"

namespace Site {

using namespace Botanik;

/**
 * @brief The destratification ladder: three bands with hysteresis on the
 *        ceiling-to-floor gap, published as a demand.
 *
 * `destrat`, dispatched SLOW. Everything here is declared in
 * tables/programs.toml; the body is hand-written beside this file. A name
 * without a leading underscore is a row or a block the POU is connected to;
 * one with is its own.
 */
class DestratController final : public Plc::Program {

public:

    /** @name VAR_INPUT
     *  @{ */

    Vars::RefIn<float> strat;
    Vars::RefIn<float> low;
    Vars::RefIn<float> med;
    Vars::RefIn<float> high;
    Vars::RefIn<float> hyst;
    Vars::RefIn<float> fan_low;
    Vars::RefIn<float> fan_med;
    Vars::RefIn<float> fan_high;

    /** @} */

    /** @name VAR_OUTPUT
     *  @{ */

    Vars::RefOut<float> demand;

    /** @} */

private:

    /** @name VAR - what this law remembers
     *  @{ */

    Plc::Staircase<3> _bands;

    /** @} */

    /** @brief Every readable row this program connects to, as bare
     *  indices: what the base sweeps for validity before each
     *  activation. Parameters are not here - an operator's number is
     *  always valid, and checking one would cost a walk to learn nothing. */
    Vars::VarRef _watched[1];

public:
    /** @brief The instance name and rate class programs.toml
     *  declares, so neither can drift from the configuration. */
    DestratController(const SetupContext& ctx, Vars::Bank& io)
        : Program(ctx, "destrat", Tasks::GROUP_SLOW, io) {}

protected:
    /** @brief Resolve every name. Runs inside the program's writer
     *  window, so an output is CLAIMED here. */
    void bind(Vars::Bank& io) override;

    /** @brief One activation of the law. */
    void run(ProgramContext& c) override;
};

inline void DestratController::bind(Vars::Bank& io) {
    strat    = io.resolve_in<float>("cli_dTStrat_degC");
    low      = io.resolve_in<float>("cli_dTStratLow_degC");
    med      = io.resolve_in<float>("cli_dTStratMed_degC");
    high     = io.resolve_in<float>("cli_dTStratHigh_degC");
    hyst     = io.resolve_in<float>("cli_dTStratHyst_degC");
    fan_low  = io.resolve_in<float>("cli_fanLowDem");
    fan_med  = io.resolve_in<float>("cli_fanMedDem");
    fan_high = io.resolve_in<float>("cli_fanHighDem");
    demand   = io.resolve_out<float>("cli_stratDem");

    // The readings this law is entitled to expect. The base walks them
    // before each activation, so an input that has stopped being believable
    // is DEGRADED whether or not the law thought to ask.
    _watched[0] = strat.r;
    set_inputs(_watched, 1);
    set_health_row(io.resolve_out<uint8_t>("prog_destrat"));
}

}  // namespace Site

#endif // SITE_PROGRAM_DESTRAT_CONTROLLER_GEN_H
